{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "A heteroaromatic morpholine-containing compound showed excellent CNS penetration in mice with a brain/plasma Kp of 11.4 and negligible P-gp efflux, directly supporting that the morpholine/heteroaromatic scaffold in the query can achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PRE-084, a morpholine-containing compound, reached brain concentrations of 773.6 ng/g at Tmax in mice with plasma at 651.5 ng/mL, demonstrating rapid CNS distribution for a morpholine-bearing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "18F-JNJ-64413739, a CF3-substituted heteroaromatic radioligand, showed high brain uptake and fast kinetics in rodents and non-human primates, supporting that CF3-heteroaryl motifs are CNS-permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Flucytosine reaches approximately 75% CSF/serum in humans, demonstrating that small heteroaromatic amino-substituted molecules can have excellent CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A CF3-substituted heteroaromatic PET ligand accumulated in mGluR2-rich brain regions in rats, demonstrating brain penetration for a structurally related CF3-heteroaryl compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A CF3-heteroaryl carboxylic acid crossed the BBB in rats by PET, albeit with low uptake; the acid group is absent in the query, so this does not indicate a failure for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have meaningful CNS access based on multiple high-transfer analogues with CF3-heteroaryl and morpholine motifs showing direct brain penetration, high CSF/serum ratios, or brain/plasma Kp >1; no contradictory evidence was identified.",
  "evidence_gaps": [
    "No direct experimental measurement of the query molecule itself.",
    "No human CSF/plasma or quantitative brain/plasma ratio for the exact query.",
    "No explicit P-gp/Bcrp efflux data for the query, though a close morpholine-containing analogue showed negligible efflux."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

